(() => {
  const html = (value = "") => String(value ?? "").replace(/[&<>'"`]/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;", "`": "&#96;" }[char]));
  const field = (label, name, value = "", type = "text", required = false) => `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${html(value)}" ${required ? "required" : ""} /></label>`;
  const area = (label, name, value = "") => `<label class="field field-wide"><span>${label}</span><textarea name="${name}" rows="3">${html(value)}</textarea></label>`;
  const options = (values, selected) => values.map(([id, label]) => `<option value="${html(id)}" ${id === selected ? "selected" : ""}>${html(label)}</option>`).join("");
  function documents(item, editingId) {
    const docs = item.documents || [];
    const editing = docs.find((entry) => entry.id === editingId) || {};
    return `<div class="view-heading"><div><p class="detail-section-title">Registro documental</p><h3>Referencias para citar</h3></div><span class="completion-label">${docs.length} referencias</span></div>
      <p class="view-intro">Referencias que pueden citarse en los requisitos. Un original archivado arriba se convierte en referencia con «Usar como fuente de requisitos». “Revisado” significa que una persona declara haberlo leído, no que el sistema lo haya verificado.</p>
      <div class="document-list">${docs.length ? docs.map((entry) => `<div class="document-row"><span class="document-icon">${html(entry.kind)}</span><div><strong>${html(entry.name)}</strong><span>${html(entry.version || "Versión por confirmar")} · ${entry.reviewedAt ? "Revisión manual registrada" : "Pendiente de revisar"}</span></div>${entry.url ? `<a href="${html(entry.url)}" target="_blank" rel="noreferrer">Abrir documento ↗</a>` : "<span>Sin enlace</span>"}<button class="text-button" data-document-edit="${html(entry.id)}" type="button">Editar</button></div>`).join("") : "<p class='route-note'>Aún no hay documentos asociados. No se presupone que PCAP, PPT o anexos estén disponibles.</p>"}</div>
      <form data-document-form class="editor-form"><h4>${editing.id ? "Editar documento" : "Añadir documento"}</h4><input name="id" type="hidden" value="${html(editing.id)}" /><div class="form-grid">${field("Nombre del documento", "name", editing.name, "text", true)}<label class="field"><span>Tipo</span><select name="kind">${options(["PCAP", "PPT", "Anexo", "Aclaración", "Otro"].map((value) => [value, value]), editing.kind || "PCAP")}</select></label>${field("Enlace del documento", "url", editing.url, "url")}${field("Versión o fecha publicada", "version", editing.version)}<label class="editor-check field-wide"><input type="checkbox" name="reviewed" ${editing.reviewedAt ? "checked" : ""} /><span>He abierto y revisado esta versión del documento.</span></label></div><div class="modal-actions"><button class="button button-dark" type="submit">Guardar documento</button>${editing.id ? '<button class="button button-quiet" data-document-new type="button">Nuevo documento</button>' : ""}</div><p class="editor-error" data-form-error role="alert"></p></form>`;
  }
  function requirements(item, editingIndex) {
    const docs = item.documents || [];
    const editing = Number.isInteger(editingIndex) ? item.requirements[editingIndex] : null;
    const req = editing || {};
    return `<div class="view-heading"><div><p class="detail-section-title">Matriz manual de cumplimiento</p><h3>Requisitos y evidencia de la empresa</h3></div><span class="completion-label">${item.requirements.filter((entry) => PliegoClaroWorkflow.confirmed(entry, docs)).length}/${item.requirements.length} trazables</span></div>
      <p class="view-intro">Separar lo que exige el documento de lo que puede demostrar la empresa. Completar una tarea no confirma por sí solo un requisito.</p>
      <div class="requirements">${item.requirements.map((entry, index) => {
        const confirmed = PliegoClaroWorkflow.confirmed(entry, docs);
        const status = confirmed ? "confirmed" : entry.status === "unknown" ? "unknown" : "pending";
        const isExpired = PliegoClaroWorkflow.expired(entry);
        return `<div class="requirement"><span class="requirement-check ${status}">${confirmed ? "✓" : "?"}</span><div class="requirement-copy"><strong>${html(entry.text)}</strong><span class="requirement-source">${html(entry.source)}${(() => { const ref = docs.find((d) => d.id === entry.documentId); const page = String(entry.citation || "").match(/\d+/); return ref?.storedDocumentId ? ` · <a href="#documento=${html(ref.storedDocumentId)}${page ? `&pagina=${page[0]}` : ""}">Ver ${page ? `pág. ${page[0]}` : "documento"}</a>` : ""; })()}</span>${entry.aiQuote ? `<q class="requirement-quote">${html(entry.aiQuote)}</q><span class="requirement-source">${entry.aiVerified ? "Cita comprobada en el texto extraído" : "Cita de la IA no encontrada: verificar"}</span>` : ""}<span class="requirement-source">Empresa: ${html(entry.companyEvidence || "evidencia pendiente")}</span><span class="requirement-status status-${status}">${confirmed ? `Confirmado por revisión manual${entry.verifiedBy ? ` · ${html(entry.verifiedBy)}` : ""}${entry.verifiedAt ? ` · ${html(new Date(entry.verifiedAt).toLocaleDateString("es-ES"))}` : ""}` : isExpired ? `Evidencia caducada el ${html(entry.evidenceValidUntil)}: no cuenta como vigente` : entry.status === "confirmed" ? "Marcado antes, pero sin trazabilidad completa" : entry.status === "partial" ? "Cumplimiento parcial" : entry.status === "unknown" ? "No localizado" : "Pendiente de comprobar"} · ${entry.critical === false ? "No decisivo" : "Decisivo"}${entry.evidenceValidUntil && !isExpired ? ` · evidencia vigente hasta ${html(entry.evidenceValidUntil)}` : ""}</span></div><button class="text-button" data-requirement-edit="${index}" type="button">Editar evidencia</button></div>`;
      }).join("")}</div>
      <form data-requirement-form class="editor-form"><h4>${editing ? "Editar requisito" : "Añadir requisito"}</h4><input name="index" type="hidden" value="${editing ? editingIndex : ""}" /><div class="form-grid">${area("Qué exige el pliego", "text", req.text)}<label class="field"><span>Documento que contiene el requisito</span><select name="documentId">${options([["", "Fuente pendiente"], ...docs.map((entry) => [entry.id, `${entry.kind} · ${entry.name}`])], req.documentId || "")}</select></label>${field("Página o cláusula", "citation", req.citation)}${area("Qué puede demostrar la empresa y con qué documento", "companyEvidence", req.companyEvidence)}${field("Enlace a la evidencia, si existe", "evidenceUrl", req.evidenceUrl, "url")}${field("Evidencia vigente hasta (certificados, seguros…)", "evidenceValidUntil", req.evidenceValidUntil, "date")}<label class="field"><span>Estado de la comprobación</span><select name="status">${options([["unknown", "No localizado"], ["pending", "Pendiente"], ["partial", "Parcial"], ["confirmed", "Confirmado por mí"]], req.status || "pending")}</select></label><label class="editor-check field-wide"><input name="critical" type="checkbox" ${req.critical !== false ? "checked" : ""} /><span>Este requisito puede cambiar la decisión de participar.</span></label></div><p class="editor-help">Para confirmar: documento revisado, página o cláusula y evidencia de la empresa. Si falta el documento, regístralo en la pestaña Documentos.</p><div class="modal-actions"><button class="button button-dark" type="submit">Guardar requisito</button>${editing ? '<button class="button button-quiet" data-requirement-new type="button">Nuevo requisito</button>' : ""}</div><p class="editor-error" data-form-error role="alert"></p></form>`;
  }
  function expediente(item) {
    return `<details class="editor-form"><summary>Editar datos del expediente</summary><form data-expediente-form><div class="form-grid">${field("Nombre de la oportunidad", "title", item.title, "text", true)}${field("Organismo", "organization", item.organization, "text", true)}${field("Importe y tratamiento del IVA", "amount", item.amount)}${field("Fecha límite exacta", "deadlineDate", item.deadlineDate, "date")}${field("Sector", "sector", item.sector)}${field("Enlace de la ficha oficial", "source", item.source, "url")}${area("Qué se compra", "summary", item.summary)}${area("Siguiente acción concreta", "nextStep", item.nextStep)}</div><p class="editor-help">La edición conserva documentos, requisitos e historial. Cambiar el cierre reabre una decisión GO para revisarla.</p><div class="modal-actions"><button class="button button-dark" type="submit">Guardar expediente</button></div><p class="editor-error" data-form-error role="alert"></p></form></details>`;
  }
  function tasks(item, tasks, team) {
    return `<section class="editor-form"><h4>Responsables y fechas de trabajo</h4><p class="editor-help">Asignar responsable no envía correos ni concede acceso: para eso, invita a la persona desde Empresa y equipo.</p>${tasks.map((task) => {
      const plan = item.taskPlans?.[task.id] || {};
      const dateWarning = plan.dueDate && item.deadlineDate && plan.dueDate > item.deadlineDate ? '<p class="editor-error" role="alert">La fecha guardada supera el cierre actual del expediente. Replanifica esta tarea; no se ha borrado la asignación.</p>' : "";
      return `<form data-task-plan="${html(task.id)}" class="task-plan-form"><strong>${html(task.title)}</strong>${dateWarning}<div class="form-grid"><label class="field"><span>Responsable</span><select name="ownerId">${options([["", "Sin asignar"], ...team.map((entry) => [entry.id, entry.name]), ...(plan.ownerId && !team.some((entry) => entry.id === plan.ownerId) ? [[plan.ownerId, "Responsable retirado · reasignar"]] : [])], plan.ownerId || "")}</select></label>${field("Fecha de la tarea", "dueDate", plan.dueDate, "date")}${area("Nota de trabajo", "note", plan.note)}</div><button class="button button-quiet" type="submit">Guardar asignación</button><p class="editor-error" data-form-error role="alert"></p></form>`;
    }).join("")}</section>`;
  }
  globalThis.PliegoClaroWorkflowUI = Object.freeze({ documents, requirements, expediente, tasks });
})();
